insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('89a0fc4e-eb7b-5dce-ae1c-7cb3d14c9f30', 'dog_registration_check', 'dog', null, 'legal', '동물등록 여부 확인하기', '2개월령 이상 반려견은 동물등록이 의무입니다. 등록 대행 동물병원이나 시·군·구청에서 할 수 있어요.', '{"species":"dog","registrationStatus":["not_registered","unknown"],"repeat":null}'::jsonb, 'legal', 1, 'easylaw_pet', 'https://easylaw.go.kr/CSP/CnpClsMain.laf?ccfNo=2&cciNo=2&cnpClsNo=1&csmSeq=1809&popMenu=ov', '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('ad6c9c04-5100-58e1-888e-caf4df925e52', 'dog_tag_check', 'dog', null, 'legal', '인식표(이름·연락처) 확인', '외출 시 소유자 연락처가 적힌 인식표를 달아야 합니다. 목걸이 상태와 글씨가 지워지지 않았는지 살펴보세요.', '{"species":"dog","repeat":"monthly"}'::jsonb, 'legal', 1, 'easylaw_pet', 'https://easylaw.go.kr', '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('02438fc5-0ab9-5b24-9a1d-8c88022854b2', 'dog_walk_kit', 'dog', null, 'outdoor', '산책 전 목줄·배변봉투·물 챙기기', '목줄(2m 이내)·배변봉투는 법정 의무입니다. 더운 날엔 물과 노면 온도도 확인하세요.', '{"species":"dog","repeat":"daily"}'::jsonb, 'safety', 1, 'easylaw_pet', 'https://easylaw.go.kr', '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('0ba69971-4218-5b8b-830e-7ac4bccca5d1', 'dog_tick_check', 'dog', null, 'outdoor', '산책 후 진드기 확인·빗질', '풀숲을 다녀왔다면 귀 뒤·겨드랑이·발가락 사이를 살펴보세요. 진드기는 손으로 터뜨리지 말고 동물병원에 문의하세요.', '{"species":"dog","months":[3,4,5,6,7,8,9,10,11],"repeat":"daily"}'::jsonb, 'safety', 1, 'kdca_sfts', 'https://dportal.kdca.go.kr', '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('6ce61018-6492-5352-a62f-460a2d3277de', 'daily_observation', null, null, 'health', '식욕·음수·배변·행동 변화 기록', '평소와 다른 점이 있으면 기록해 두세요. 병원에 갈 때 가장 도움이 되는 정보입니다.', '{"repeat":"daily"}'::jsonb, 'health', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('b11e4159-3ece-5811-a6b2-a3754d94d936', 'weekly_weight', null, null, 'health', '체중 재서 기록하기', '같은 시간·같은 저울로 재면 변화를 알아차리기 쉬워요.', '{"repeat":"weekly"}'::jsonb, 'health', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('57db0e5c-ac36-5159-8dce-b1f720da2d7f', 'senior_watch', null, 'senior', 'health', '노령 반려동물 음수량·활동량 살피기', '물을 갑자기 많이 마시거나 움직임이 줄면 기록하고 동물병원과 상담하세요.', '{"lifeStage":["senior"],"repeat":"weekly"}'::jsonb, 'health', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('10de6972-99b1-594d-9feb-d59059c2a499', 'home_poison_check', null, null, 'poison', '집안 위험 물질 점검', '사람 약, 초콜릿, 포도, 자일리톨, 양파, 세제, 백합류 식물이 손 닿는 곳에 있는지 확인하세요.', '{"repeat":"monthly"}'::jsonb, 'safety', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('b213c80c-3421-5bdc-af1f-9bca33ca5c91', 'cat_litter', 'cat', null, 'cat_env', '화장실 청소 (매일)', '매일 치우면 배변 변화도 빨리 알 수 있고, 톡소포자충 예방에도 도움이 됩니다. 장갑을 끼고 손을 씻으세요.', '{"species":"cat","repeat":"daily"}'::jsonb, 'health', 1, 'kdca_toxo', 'https://dportal.kdca.go.kr', '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('6ab9ed14-4e18-540a-ad05-8a975453fab7', 'cat_env_check', 'cat', null, 'cat_env', '수직공간·숨을 곳·끈류 점검', '올라갈 곳과 숨을 곳이 있는지, 실·끈·고무줄이 바닥에 떨어져 있지 않은지 살펴보세요.', '{"species":"cat","repeat":"monthly"}'::jsonb, 'general', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('36dca07f-4664-5d9a-807b-9d94f33826eb', 'multi_pet_watch', null, null, 'behavior', '다동물 가정: 식사·화장실 따로 쓰는지 확인', '서로 눈치 보며 못 먹거나 화장실을 피하면 스트레스 신호일 수 있어요.', '{"multiPet":true,"repeat":"weekly"}'::jsonb, 'lifestyle', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
insert into public.care_task_templates (id, key, species, life_stage, category, title, description, rule_json, priority, version, source_id, source_url, reviewed_at, status) values ('7ef37a13-a6f1-56fd-9a47-784ccf6fcad9', 'insurance_renewal', null, null, 'insurance', '보험 갱신일·청구 서류 확인', '갱신일이 다가오면 보장 내용이 바뀌는지 보험사 고객센터에서 확인하세요.', '{"insuranceStatus":["insured"],"repeat":"monthly"}'::jsonb, 'lifestyle', 1, null, null, '2026-08-31', 'published') on conflict (key) do update set title = excluded.title, description = excluded.description, rule_json = excluded.rule_json, priority = excluded.priority, version = excluded.version, reviewed_at = excluded.reviewed_at;
